from pathlib import Path
import re,html,difflib,json,hashlib,markdown
O=Path(__file__).resolve().parent;R=O.parents[3]
def render(s):return markdown.markdown(re.sub(r'<!--\s*@[^>]*-->','',s),extensions=['extra','sane_lists'])
def image(n,c):return '<figure><a href="'+n+'.png"><img loading="lazy" src="'+n+'.png" alt="'+html.escape(c,quote=True)+'"></a><figcaption>'+c+'</figcaption></figure>'
before=(O/'Color_Flashlight.before.md').read_text(encoding='utf-8');after=(R/'commons/maps/Color_Flashlight/final.md').read_text(encoding='utf-8')
assert after==(O/'Color_Flashlight.after.md').read_text(encoding='utf-8')
css=re.search(r'<style>(.*?)</style>',(O.parent/'2026-09-23-array-molnar-volume/index.html').read_text(encoding='utf-8'),re.S)[1]
a=before.split('\n\n');b=after.split('\n\n');pairs=[]
for tag,i,j,k,l in difflib.SequenceMatcher(None,a,b,autojunk=False).get_opcodes():
 if tag=='equal':continue
 pairs.append('<div class="pair"><div><h3>Before</h3>'+(render('\n\n'.join(a[i:j])) or '<p>New encounter and shared illustration, inserted after the side-cube comparison.</p>')+'</div><div><h3>Now</h3>'+render('\n\n'.join(b[k:l]))+'</div></div>')
page='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Flashlight — face by face</title><style>'+css+'</style></head><body><main>'
page+='''<div class="eyebrow">Ada Research · Colour · 23 September 2026</div><h1>Face by face.</h1><p class="intro">No face has been repainted.<br>The light has moved.</p><p class="status">A seven-division faceted sphere is now part of <strong>Color_Flashlight</strong>. Two new encounter paragraphs and the native paired illustration are in <strong>final.md</strong>.</p><nav><a href="#encounter">In the hall</a><a href="#comparison">What changed</a><a href="#reading">Read the chapter</a><a href="#evidence">Evidence</a><a href="/compose/sources?map=Color_Flashlight&amp;doc=final">Read and comment</a></nav>'''
page+='<section id="encounter"><h2>The same light meets another body</h2>'+image('arrival','The current hall: the pale faceted sphere stands to the left of the board. The four lamps, side cube and original grid cube remain.')+image('same-sphere-moving-light','Two native Godot captures from the same camera, cropped and labelled for the book. A supplied grabber moves the existing red lamp; the sphere, its material and the other lamps stay fixed.')+image('two-colours','Red from one side, blue from the other. All four lamps remain on. This is the actual placed receiver in the museum, not a painted colour model.')+'<p>The sphere is 1.7 metres tall on a low pedestal, centred 1.5 metres above the floor. Seven describes the divisions around it. Its 42 triangles have flat normals, so the light can reveal the construction we encountered among the primitives.</p></section>'
page+='<section id="comparison"><h2>A return within the existing lesson</h2><p>The chapter keeps its opening, lamp comparisons, code excerpt, limits of RGB rendering and handoff to Nails. The addition follows the existing invitation to carry the light beyond the board. Five or seven divisions can be authored; this hall uses seven. No new visitor controls are needed.</p>'+''.join(pairs)+'<p><a href="Color_Flashlight.diff">Exact manuscript diff</a> · <a href="source-changes.diff">Source and companion changes</a></p></section>'
page+='<section id="reading"><article class="reading">'+render(after)+'</article></section>'
page+='''<section id="evidence" class="evidence"><h2>What was checked</h2><p>43 focused checks pass inside the isolated production museum: placement and 180-degree yaw, flat outward normals, matching collision, supporting floor and three standing-body clearances, all four lamps’ pickup/movement/release and the rendered change when the held red lamp changes sides. The same receiver material remains in place. The five-division authoring option and legacy installations were checked too.</p><p>The first placement check caught the grid interpreting an unregistered numeric key as rotation. Registering that single key fixes the placement. Degenerate pole triangles were removed before making flat normals and collision. Native renders and the final book figure were inspected.</p><p>These are desktop Compatibility renders and supplied grabber motion. They do not establish tracked-controller reach, a complete walk around the pedestal, headset comfort, learner response or Quest performance. Existing unrelated startup UID and renderer warnings are retained in the log.</p><p><a href="report.json">Runtime checks</a> · <a href="source_manifest.json">Capture inputs</a> · <a href="verification.json">Publication checks</a> · <a href="SUMMARY.md">Findings and decisions</a></p></section><footer>Next: Color_Nails — where the chosen colour reaches the acting body.</footer></main></body></html>'''
(O/'index.html').write_text(page,encoding='utf-8')
diffs=[]
for relative in json.loads((O/'baseline-hashes.json').read_text()):
 if relative.endswith('/final.md'):continue
 diffs.extend(difflib.unified_diff((O/'before'/relative).read_text(encoding='utf-8').splitlines(True),(R/relative).read_text(encoding='utf-8').splitlines(True),fromfile='before/'+relative,tofile=relative))
(O/'source-changes.diff').write_text(''.join(diffs),encoding='utf-8')
print('Built review page with current canonical reading and exact diffs.')
